function privacyNote(){return `<section class="profile-privacy" aria-label="家长使用提醒"><strong>陪孩子一起发现</strong><p class="privacy-summary">请由家长登录和管理，只填写孩子的昵称与年龄段，不填写真实姓名等私人信息。</p><p class="privacy-location">资料可能保存在中国大陆以外的地区，请了解后再使用。</p><details id="privacy-details" class="privacy-details"><summary>隐私与资料说明</summary><div class="privacy-detail-content"><p><strong>我们使用哪些资料？</strong><br>家长邮箱用于登录验证；孩子的昵称、年龄段和探索记录用于保存学习进度。昵称仍可能让人认出孩子，请不要填写真实姓名、生日、学校、联系方式或健康资料。</p><p><strong>谁帮助提供服务？</strong><br>验证码邮件由 Resend 发送，它会接收家长邮箱；账号、儿童资料和学习记录由 Cloudflare 保存和处理。若设置登录密码，仅保存不可还原的密码校验值，不保存明文密码。我们不能保证资料保存在中国大陆。</p><p><strong>如何保管记录？</strong><br>可以在“我的家庭”导出资料，建议定期留一份备份。网上保存也可能发生丢失，请妥善保管导出文件，不要公开分享。</p><p><strong>归档会删除资料吗？</strong><br>不会。归档只是暂时收起档案，记录仍保留，也可以恢复，并非永久删除。需要处理账号或资料，请联系本站管理员。</p></div></details></section>`}
function authPolicyNote(){
 const allowed=authConfig?.allowedDomains||[];
 const policy=!authConfig?.registrationEnabled?'新账号注册暂未开放。已有账号仍可使用验证码登录。':allowed.length?`新用户可使用这些邮箱：${allowed.map(escapeHTML).join('、')}。验证后即可登录；首次使用会自动创建账号。`:'暂未开放新用户注册，已有账号仍可登录。';
 return `<p id="auth-policy-note" class="muted-note">${policy} 暂不支持的邮箱，请联系管理员。</p>`;
}
function renderPasswordLogin(message=''){
 authEpoch++;authBusy=false;authChallenge=null;passwordRecovery=false;clearInterval(authTimer);
 $('#account-content').innerHTML=`<div class="account-card"><span class="account-kicker">WELCOME BACK</span><h1 id="account-heading">用密码继续探索</h1><p>账号就是你的家长邮箱。首次使用请先用邮箱验证码注册。</p><div class="form-actions auth-methods"><button id="switch-code-login" class="button outline" type="button">邮箱验证码</button><button class="button primary" type="button" aria-current="true">邮箱与密码</button></div><form id="password-login-form" class="account-form"><label>家长邮箱<input id="password-email" type="email" autocomplete="username" maxlength="254" required value="${escapeHTML(authEmail)}"></label><label>登录密码<input id="login-password" type="password" autocomplete="current-password" required aria-describedby="password-login-help"></label><p id="password-login-help" class="muted-note">忘记密码或尚未设置？可使用邮箱验证码登录。</p><button id="password-login" class="button primary" type="submit">登录 →</button><p id="auth-message" class="form-message ${message?'error':''}" role="status">${escapeHTML(message)}</p></form><button id="forgot-password" class="text-button" type="button">忘记密码？用邮箱验证后重设</button>${privacyNote()}</div>`;
 $('#switch-code-login').addEventListener('click',()=>{if(authBusy)return;authEmail=$('#password-email').value;renderAuth()});$('#forgot-password').addEventListener('click',()=>{if(authBusy)return;authEmail=$('#password-email').value;passwordRecovery=true;renderAuth('请用邮箱验证码登录，验证后即可设置新密码。','info')});
 $('#password-login-form').addEventListener('submit',event=>{event.preventDefault();if(authBusy)return;action($('#password-login'),async()=>{const flow=authEpoch;authBusy=true;$('#switch-code-login').disabled=true;$('#forgot-password').disabled=true;try{authEmail=$('#password-email').value.trim();const input=$('#login-password'),password=input.value;input.value='';const result=await api('/api/auth/password-login',{method:'POST',body:{email:authEmail,password}});if(flow!==authEpoch)return;authEmail='';await acceptSession(result)}finally{if(flow===authEpoch){authBusy=false;$('#switch-code-login').disabled=false;$('#forgot-password').disabled=false}}},'auth-message')});
}
function openPasswordSetup(){
 if(!session||$('#password-dialog'))return;let submitting=false;const owner=session.user.id,epoch=contextEpoch,opener=document.activeElement,dialog=document.createElement('dialog');dialog.id='password-dialog';dialog.className='password-dialog';dialog.setAttribute('aria-labelledby','password-setup-title');
 dialog.innerHTML=`<div class="password-card"><h2 id="password-setup-title">${session.user.hasPassword?'设置新密码':'设置一个登录密码'}</h2><p>以后可以用邮箱与密码登录，也可以继续使用邮箱验证码。</p><form id="set-password-form" class="account-form"><label>新密码<input id="new-password" type="password" autocomplete="new-password" required aria-describedby="new-password-help"></label><p id="new-password-help" class="muted-note">至少8位，最长128个字符，不强制字母、数字或符号组合。建议使用更长、与其他网站不同的密码。</p><label>再输入一次<input id="confirm-password" type="password" autocomplete="new-password" required></label><p class="muted-note">保存后，其他设备会退出登录。</p><button id="save-password" class="button primary" type="submit">保存密码</button><p id="password-message" class="form-message" role="status"></p></form><button id="skip-password" class="text-button" type="button">${session.user.hasPassword?'取消，保留原密码':'暂不设置，继续使用验证码'}</button></div>`;
 document.body.append(dialog);dialog.addEventListener('cancel',event=>{if(submitting)event.preventDefault()});dialog.addEventListener('keydown',trapDialogFocus);dialog.addEventListener('close',()=>{dialog.querySelectorAll('input').forEach(input=>input.value='');dialog.remove();syncDialogUI();if(opener?.isConnected)opener.focus({preventScroll:true});else $('#account-heading')?.focus({preventScroll:true})},{once:true});$('#skip-password').addEventListener('click',()=>dialog.close());
 $('#set-password-form').addEventListener('submit',event=>{event.preventDefault();action($('#save-password'),async()=>{if(!await ensureSaved()||session?.user.id!==owner||contextEpoch!==epoch)return;const password=$('#new-password').value,again=$('#confirm-password').value;if(Array.from(password).length<8||Array.from(password).length>128)throw new Error('请输入8至128个字符的密码。');if(password!==again)throw new Error('两次输入的密码不一致，请再核对一下。');$('#new-password').value='';$('#confirm-password').value='';$('#skip-password').disabled=true;submitting=true;try{const result=await api('/api/auth/password',{method:'POST',body:{password}});if(session?.user.id!==owner||contextEpoch!==epoch)return;Object.assign(session,{user:result.user,csrfToken:result.csrfToken,canSetPassword:result.canSetPassword});dialog.close();toast('密码已保存。下次可用邮箱与密码登录。');if(location.hash==='#account')renderFamily()}finally{submitting=false;if($('#skip-password'))$('#skip-password').disabled=false}},'password-message')});dialog.showModal();syncDialogUI();$('#new-password').focus();
}
function passwordSettingsHTML(){return `<section class="account-section password-settings"><h2>登录密码</h2><p>${session?.user.hasPassword?'已设置密码，也可以随时使用邮箱验证码登录。':'还未设置密码，目前使用邮箱验证码登录。'}</p><button id="manage-password" class="button outline">${session?.user.hasPassword?'设置新密码':'设置登录密码'}</button><p class="muted-note">需要最近10分钟内的邮箱验证。若提示验证过期，请退出并使用邮箱验证码重新登录。</p></section>`}
function bindPasswordSettings(){$('#manage-password')?.addEventListener('click',openPasswordSetup)}

function renderAuth(message='',tone='error'){
 authEpoch++;authBusy=false;authConsent=false;authChallenge=null;clearInterval(authTimer);$('#account-content').innerHTML=`<div class="account-card"><span class="account-kicker">LITTLE LAB / YOUR FAMILY SPACE</span><h1 id="account-heading">把每次发现，留在成长里。</h1><p>用家长邮箱收取验证码，即可登录或注册。</p><div class="form-actions auth-methods"><button class="button primary" type="button" aria-current="true">邮箱验证码</button><button id="switch-password-login" class="button outline" type="button">邮箱与密码</button></div>${authConfig?.setupRequired?'<p class="form-message">注册与邮件服务尚在配置中。暂不接收新账号或儿童资料，请稍后再来。</p>':''}<form id="email-form" class="account-form"><label>家长邮箱<input id="auth-email" type="email" autocomplete="email" maxlength="254" required placeholder="name@example.com" value="${escapeHTML(authEmail)}"></label>${authPolicyNote()}<label class="check-label"><input id="auth-consent" type="checkbox" required><span>我是成年家长或监护人，已阅读下方《隐私与资料说明》，同意用邮箱登录；首次使用时自动注册。</span></label><button id="request-code" class="button primary" type="submit" ${authConfig?.setupRequired?'disabled':''}>发送邮箱验证码 →</button><p id="auth-message" class="form-message ${message?escapeHTML(tone):''}" role="status">${escapeHTML(message)}</p></form><button type="button" class="disabled-provider" disabled>微信授权登录 · 后续开放</button>${recoverySnapshot?'<div class="cloud-retry-box"><p>当前页面保留一份未保存草稿。离开前可导出到自己的设备；文件包含私人记录，请勿公开。</p><button id="export-expired-draft" class="button outline">导出未保存草稿</button></div>':''}${privacyNote()}</div>`;
 $('#switch-password-login').addEventListener('click',()=>{if(authBusy)return;authEmail=$('#auth-email').value;renderPasswordLogin()});
 $('#export-expired-draft')?.addEventListener('click',()=>downloadJSON(recoverySnapshot,'little-lab-recovery-'+localDate()+'.json'));
 $('#email-form').addEventListener('submit',event=>{event.preventDefault();if(authBusy)return;action($('#request-code'),async()=>{const flow=authEpoch;authEmail=$('#auth-email').value.trim().toLowerCase();authConsent=$('#auth-consent').checked;if(!authConsent)throw new Error('请先阅读隐私说明，并勾选家长确认。');setAuthBusy(true);try{const result=await api('/api/auth/request-code',{method:'POST',body:{email:authEmail,intent:'continue',adultConsent:authConsent,privacyAccepted:authConsent}});if(flow!==authEpoch)return;authChallenge=result.challengeId;resendAt=Date.now()+60000;renderVerify()}finally{if(flow===authEpoch)setAuthBusy(false)}},'auth-message')});
}
function renderVerify(message=''){
 $('#account-content').innerHTML=`<div class="account-card"><span class="account-kicker">VERIFY YOUR EMAIL</span><h1 id="account-heading">请查收邮箱验证码</h1><p>已为 <strong>${escapeHTML(authEmail)}</strong> 提交验证码申请。如果邮箱符合登录／注册条件，验证码将发送到该邮箱。</p>${authPolicyNote()}<form id="verify-form" class="account-form"><label>8位验证码<input id="auth-code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{8}" maxlength="8" minlength="8" required placeholder="输入8位数字"></label><button id="verify-code" class="button primary" type="submit">验证并继续 →</button><p id="auth-message" class="form-message" role="status">${escapeHTML(message)}</p></form><div class="form-actions account-section"><button id="resend-code" class="text-button" disabled>稍后重新发送</button><button id="change-email" class="text-button">更换邮箱</button></div><p class="muted-note">验证码10分钟内有效，请勿向任何人透露。若未收到，请检查垃圾邮件，并确认邮箱拼写和上方开放规则；仍未收到可联系管理员检查邮件服务。关闭页面后需重新申请。</p></div>`;
 const tick=()=>{const b=$('#resend-code');if(!b){clearInterval(authTimer);return}const seconds=Math.max(0,Math.ceil((resendAt-Date.now())/1000));b.disabled=authBusy||seconds>0;b.textContent=seconds?`${seconds}秒后可重发`:'重新发送验证码'};clearInterval(authTimer);tick();authTimer=setInterval(tick,1000);
 $('#change-email').addEventListener('click',()=>{if(authBusy)return;renderAuth()});$('#resend-code').addEventListener('click',()=>action($('#resend-code'),async()=>{if(authBusy||!authConsent)return;const flow=authEpoch;setAuthBusy(true);try{const r=await api('/api/auth/request-code',{method:'POST',body:{email:authEmail,intent:'continue',adultConsent:authConsent,privacyAccepted:authConsent}});if(flow!==authEpoch)return;authChallenge=r.challengeId;resendAt=Date.now()+60000;renderVerify('已重新申请。请使用最新邮件里的验证码。')}finally{if(flow===authEpoch)setAuthBusy(false)}},'auth-message'));
 $('#verify-form').addEventListener('submit',event=>{event.preventDefault();if(authBusy)return;action($('#verify-code'),async()=>{const flow=authEpoch;setAuthBusy(true);try{const result=await api('/api/auth/verify-code',{method:'POST',body:{challengeId:authChallenge,code:$('#auth-code').value.trim()}});if(flow!==authEpoch)return;clearInterval(authTimer);authChallenge=null;authEmail='';authConsent=false;await acceptSession(result)}finally{if(flow===authEpoch)setAuthBusy(false)}},'auth-message')});$('#auth-code').focus();
}
async function acceptSession(result,{resume=false}={}){
 const promptPassword=!resume&&(!result.user.hasPassword||passwordRecovery);passwordRecovery=false;
 const flow=++authEpoch;authBusy=false;if(recoverySnapshot&&recoverySnapshot.userId!==result.user.id)recoverySnapshot=null;
 clearPrivateState({preservePreparation:resume});const owner=session={user:result.user,csrfToken:result.csrfToken,canSetPassword:result.canSetPassword};
 const ownsSession=()=>session===owner&&authEpoch===flow;
 try{if(!renderActivityDiagram){const diagrams=await import('./diagrams.js');if(!ownsSession())return;({renderActivityDiagram,resolveAgeProtocol}=diagrams);}}
 catch(error){if(!ownsSession())return;clearPrivateState();renderAuth('课程资源暂时未加载，请重新登录重试。');syncView();throw error;}
 if(!ownsSession())return;children=result.children||[];renderFamilyBar();const first=children.find(c=>!c.archivedAt);
 if(first){await selectChild(first.id,{skipSave:true});if(!ownsSession())return;if(location.hash==='#account'||!location.hash)history.replaceState(null,'','#lab');}
 else history.replaceState(null,'','#account');
 if(!ownsSession())return;renderFamily();syncView();if(promptPassword)openPasswordSetup();
}
function childForm(child=null){return `<form id="child-form" class="account-form"><label>孩子的昵称<input id="child-nickname" maxlength="24" required autocomplete="off" placeholder="例如：小探险家，不填真实姓名" value="${escapeHTML(child?.nickname||'')}"></label><label>年龄段<select id="child-age">${ageBands.map(age=>`<option value="${age}" ${child?.ageBand===age?'selected':''}>${ages[age].label}岁 · ${ages[age].name}</option>`).join('')}</select></label><label class="check-label"><input id="child-consent" type="checkbox" required><span>我是孩子的家长或监护人，已阅读下方隐私说明，同意在账号中保存孩子的昵称、年龄段和探索记录。</span></label><div class="form-actions"><button class="button primary" id="save-child" type="submit">${child?'保存档案':'创建儿童档案'} →</button>${children.some(c=>!c.archivedAt)?'<button class="text-button" type="button" id="cancel-child">取消</button>':''}</div><p id="child-message" class="form-message" role="status"></p></form>`}
function renderChildEditor(child=null){$('#account-content').innerHTML=`<div class="account-card"><span class="account-kicker">A SMALL PROFILE, A LONG JOURNEY</span><h1 id="account-heading">${child?'编辑儿童档案':'先认识这位小探险家'}</h1><p>一个家长账号可管理多个孩子。每个孩子的记录独立保存。</p>${childForm(child)}${archivedChildrenHTML()}${passwordSettingsHTML()}<button type="button" id="editor-logout" class="text-button">退出登录</button>${privacyNote()}</div>`;bindPasswordSettings();$('#cancel-child')?.addEventListener('click',renderFamily);$('#editor-logout')?.addEventListener('click',()=>action($('#editor-logout'),logout,'child-message'));bindRestoreChildren();$('#child-form').addEventListener('submit',event=>{event.preventDefault();action($('#save-child'),async()=>{const owner=session,epoch=contextEpoch,nickname=$('#child-nickname').value.trim(),ageBand=$('#child-age').value,guardianConsent=$('#child-consent')?.checked;if(!await ensureSaved()||session!==owner||contextEpoch!==epoch)return;const result=await api(child?'/api/children/'+encodeURIComponent(child.id):'/api/children',{method:child?'PATCH':'POST',body:child?{nickname,ageBand}:{nickname,ageBand,guardianConsent}});if(session!==owner||contextEpoch!==epoch)return;const existing=children.findIndex(c=>c.id===result.child.id);if(existing>=0)children[existing]=result.child;else children.push(result.child);await selectChild(result.child.id,{skipSave:true});history.replaceState(null,'','#lab');syncView()},'child-message')})}
function renderFamily(){
 if(!session)return;if(!children.some(c=>!c.archivedAt)){renderChildEditor();return}
 $('#account-content').innerHTML=`<div class="family-heading"><div><span class="account-kicker">OUR FAMILY / DISCOVERY TOGETHER</span><h1 id="account-heading">我们的探索空间</h1><p class="muted-note">${escapeHTML(session.user.email)} · ${session.user.role==='admin'?'管理员':'家长账号'}</p></div><button id="logout" class="text-button">退出登录</button></div><div class="child-grid">${children.filter(c=>!c.archivedAt).map(c=>`<article class="child-card ${activeChild?.id===c.id?'active':''}"><h3>${escapeHTML(c.nickname)}</h3><p>${escapeHTML(c.ageBand)}岁 · 独立保存的成长记录</p><div class="form-actions"><button class="button ${activeChild?.id===c.id?'primary':'outline'}" data-select-child="${escapeHTML(c.id)}">${activeChild?.id===c.id?'继续探索':'切换到这个孩子'}</button><button class="text-button" data-edit-child="${escapeHTML(c.id)}">编辑</button><button class="text-button" data-archive-child="${escapeHTML(c.id)}">归档</button></div></article>`).join('')}<article class="child-card"><h3>添加小探险家</h3><p>只填昵称和年龄段，最多可添加8位小探险家。</p><button id="add-child" class="button outline" ${children.filter(c=>!c.archivedAt).length>=8?'disabled':''}>＋ 新建儿童档案</button></article></div>${archivedChildrenHTML()}<p id="family-message" class="form-message page-status" role="status"></p>${recoverySnapshot&&recoverySnapshot.userId===session.user.id?'<div class="cloud-retry-box"><strong>有一份尚未保存的记录</strong><p>这些修改还未保存到账号。请先导出留存，关闭页面会丢失。</p><button id="export-recovery" class="button outline">导出未保存记录</button><button id="discard-recovery" class="text-button">放弃这份记录</button></div>':''}${saveConflict?'<div class="cloud-retry-box"><strong>另一设备已更新记录</strong><p>另一台设备保存了新内容。请先导出此页面尚未保存的记录，再查看最新记录，避免丢失修改。</p><button id="download-unsaved" class="button outline">导出待保存记录</button><button id="reload-cloud" class="text-button">查看最新记录</button></div>':saveError?'<div class="cloud-retry-box"><strong>部分修改还未保存</strong><p>'+escapeHTML(saveError)+'</p><button id="retry-family-save" class="button outline">重试保存</button><button id="download-unsaved" class="text-button">导出待保存记录</button></div>':''}${passwordSettingsHTML()}<section class="account-section"><h2>记录由你保管</h2><div class="export-actions"><button id="export-account" class="button outline">导出全部家庭记录</button><button id="export-account-parts" class="button outline">分卷导出大份记录</button><button id="export-part-again" class="text-button" hidden>重新下载上一卷</button><button id="logout-all-note" class="button outline">账号与资料说明</button></div><p class="muted-note">建议定期导出备份，请勿公开分享。归档只是收起档案，记录仍保留，可随时恢复。</p></section><section class="account-section"><details id="import-details"><summary>把这个浏览器的旧记录导入当前孩子</summary><p>这里可以找回旧版记录。请选择对应的孩子，确认后再导入；原记录会保留，未开放的活动不能导入。</p><div id="legacy-import-preview"></div></details></section>${privacyNote()}`;
 bindPasswordSettings();bindRestoreChildren();$('#export-recovery')?.addEventListener('click',()=>downloadJSON(recoverySnapshot,'little-lab-recovery-'+localDate()+'.json'));$('#discard-recovery')?.addEventListener('click',()=>{if(confirm('放弃这份未保存的记录？账号中已保存的记录不会改变。')){recoverySnapshot=null;renderFamily()}});$('#logout').addEventListener('click',()=>action($('#logout'),logout,'family-message'));$('#add-child').addEventListener('click',()=>renderChildEditor());$$('[data-select-child]').forEach(b=>b.addEventListener('click',()=>action(b,async()=>{if(await selectChild(b.dataset.selectChild)){location.hash='#lab';syncView()}},'family-message')));$$('[data-edit-child]').forEach(b=>b.addEventListener('click',()=>renderChildEditor(children.find(c=>c.id===b.dataset.editChild))));$$('[data-archive-child]').forEach(b=>b.addEventListener('click',()=>action(b,async()=>{const owner=session,epoch=contextEpoch,child=children.find(c=>c.id===b.dataset.archiveChild);if(!confirm(`将“${child.nickname}”归档？记录会保留，但从孩子列表中收起，之后可以恢复。`))return;if(!await ensureSaved()||session!==owner||contextEpoch!==epoch)return;await api('/api/children/'+encodeURIComponent(child.id),{method:'DELETE',body:{}});if(session!==owner||contextEpoch!==epoch)return;children=children.map(c=>c.id===child.id?{...c,archivedAt:new Date().toISOString()}:c);if(activeChild?.id===child.id){activeChild=null;experiments=[];state=freshState();const next=children.find(c=>!c.archivedAt);if(next)await selectChild(next.id,{skipSave:true})}renderFamily();renderFamilyBar();syncView()},'family-message')));
 $('#export-account').addEventListener('click',()=>action($('#export-account'),async()=>{if(!await ensureSaved())return;const owner=session,epoch=contextEpoch;const data=await exportProgressAccount({api,isCurrent:()=>session===owner&&contextEpoch===epoch});if(session!==owner||contextEpoch!==epoch)return;downloadJSON(data,'little-lab-family-'+localDate()+'.json')},'family-message'));bindSegmentedExport();$('#logout-all-note').addEventListener('click',()=>toast('账号由家长管理。需要停用或恢复档案，请联系本站管理员。'));
 $('#download-unsaved')?.addEventListener('click',()=>downloadJSON({exportedAt:new Date().toISOString(),warning:'此文件是尚未保存的修改备份，不代表账号中已保存的进度或已开放的活动',child:{nickname:activeChild?.nickname,ageBand:activeChild?.ageBand},state,recordDrafts:recoveryDraftRecords()},'little-lab-unsaved-'+localDate()+'.json'));
 $('#retry-family-save')?.addEventListener('click',()=>action($('#retry-family-save'),async()=>{await flushSave();renderFamily()},'family-message'));$('#reload-cloud')?.addEventListener('click',async()=>{if(!confirm('是否已导出此页面尚未保存的记录？继续会换成账号中的最新记录，并放弃此页面的修改。'))return;saveConflict=false;dirty=false;await selectChild(activeChild.id,{skipSave:true});renderFamily()});
 $('#import-details').addEventListener('toggle',()=>{if($('#import-details').open)renderLegacyImport()});
}
async function logout(){if(dirty&&!await ensureSaved()){if(!confirm('部分修改尚未保存。确定退出并放弃这些未保存修改吗？可先取消并导出。'))return}await api('/api/auth/logout',{method:'POST',body:{}});clearPrivateState();history.replaceState(null,'','#account');renderAuth();syncView()}
function bindSegmentedExport(){
 let exporter=null,last=null,owner=null,epoch=null;const button=$('#export-account-parts'),again=$('#export-part-again');
 button.addEventListener('click',async()=>{let restart=false;const value=await action(button,async()=>{if(!exporter){if(!await ensureSaved())return;owner=session;epoch=contextEpoch;exporter=createProgressExportParts({api,isCurrent:()=>session===owner&&contextEpoch===epoch})}let part;try{part=await exporter.next({acknowledgedPart:last?.part||0})}catch(error){if(error.code==='EXPORT_CONTEXT_CHANGED'){exporter=null;last=null;again.hidden=true;restart=true}throw error}if(!part||session!==owner||contextEpoch!==epoch)return;last=part;downloadJSON(part,'little-lab-family-'+part.exportId+'-part-'+part.part+'.json');again.hidden=false;setMessage('family-message',part.complete?`已生成全部 ${part.part} 卷。请保留同一编号的所有文件，检查浏览器已下载；单卷不是完整备份。`:`已生成第 ${part.part} 卷，请确认下载后继续下一卷。尚未完成全部导出。`);return part},'family-message');if(restart)button.textContent='重新开始分卷导出';if(value){button.textContent=value.complete?'分卷导出已完成':'已保存本卷，下载下一卷';button.disabled=value.complete}});
 again.addEventListener('click',()=>{if(last&&session===owner&&contextEpoch===epoch)downloadJSON(last,'little-lab-family-'+last.exportId+'-part-'+last.part+'.json')});
}
function downloadJSON(value,filename){const blob=new Blob([JSON.stringify(value)],{type:'application/json'}),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;link.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
function readLegacyState(){let value;try{value=JSON.parse(localStorage.getItem(KEY)||'null')}catch{return null}if(!isRecord(value))return null;const previous=state;try{state=normalizeState(value,activeChild);state.recordSchemaVersion=value.recordSchemaVersion;migrateLegacyRecords();return JSON.parse(JSON.stringify(state))}finally{state=previous}}
function renderLegacyImport(){
 const destinationId=activeChild?.id,destinationEpoch=contextEpoch,destinationUser=session?.user.id,client=progressClient,legacy=readLegacyState(),root=$('#legacy-import-preview');
 const records=legacy?legacyImportRecords(legacy):[];if(!records.length){root.innerHTML='<p class="muted-note">没有找到可读取的旧记录。原有资料没有被修改。</p>';return}
 root.innerHTML=`<p><strong>目标孩子：${escapeHTML(activeChild?.nickname||'请先选择孩子')}</strong><br>检测到 ${records.length} 组旧记录。按项导入，原始数据不会清除。</p><p class="muted-note">只接受已开放关卡，不覆盖不同内容。若中途失败，已成功的项目保留，尚未完成的项目可以重试；导入不会自动解锁新关卡。</p><label class="import-confirm"><input id="import-consent" type="checkbox"> 我确认这些是当前孩子的记录，并同意上传到这个家庭账号。</label><button id="import-legacy" class="button outline" disabled>导入到 ${escapeHTML(activeChild?.nickname||'当前孩子')}</button><p id="import-message" class="form-message" role="status"></p>`;
 $('#import-consent').addEventListener('change',()=>$('#import-legacy').disabled=!$('#import-consent').checked);
 $('#import-legacy').addEventListener('click',()=>action($('#import-legacy'),async()=>{
  const owns=()=>destinationId===activeChild?.id&&destinationEpoch===contextEpoch&&destinationUser===session?.user.id&&client===progressClient;
  if(!$('#import-consent').checked||!owns()||!await ensureSaved()||!owns())return;if(client.summaries().some(r=>r.hasNotes)&&!confirm('这个孩子已有记录，请先导出备份。导入不会替换已有的不同内容。继续吗？'))return;
  let completed=0;try{for(const item of records){if(!owns())return;await client.importRecord(item.key,item.record,{confirmed:true});completed++;if(!owns())return;setMessage('import-message',`已保存 ${completed} / ${records.length} 项。`)}const result=await client.load();if(!owns())return;applyProgressSummaries(result.items);if(!current()?.locked)await loadSelectedProgress(destinationEpoch);if(!owns())return;renderFamilyBar();setMessage('import-message','导入成功，已保存到账号。此浏览器里的旧记录仍保留。')}catch(error){if(owns())setMessage('import-message',`已保存 ${completed} / ${records.length} 项。${error.message} 原始旧记录仍保留，可核对后重试。`,true)}
 },'import-message'));
}

async function renderAdmin(){
 if(session?.user?.role!=='admin')return;const epoch=contextEpoch;$('#admin-content').innerHTML=`<div class="admin-heading"><div><span class="account-kicker">ADMINISTRATION / FAMILY LAB</span><h1 id="admin-heading">管理中心</h1></div><a href="#lab" class="text-button">返回探索</a></div><div class="admin-tabs" role="group" aria-label="管理分类"><button data-admin-section="users" aria-pressed="${adminSection==='users'}">用户与关卡</button><button data-admin-section="settings" aria-pressed="${adminSection==='settings'}">注册设置</button><button data-admin-section="audit" aria-pressed="${adminSection==='audit'}">操作记录</button></div><p id="admin-message" class="form-message" role="status"></p><div id="admin-panel"><p class="account-loading">正在读取管理数据…</p></div>`;
 $$('[data-admin-section]').forEach(b=>b.addEventListener('click',()=>{adminSection=b.dataset.adminSection;renderAdmin()}));try{if(adminSection==='users')await renderAdminUsers();else if(adminSection==='settings'){const result=await api('/api/admin/settings');if(epoch===contextEpoch)renderAdminSettings(result)}else{const result=await api('/api/admin/audit?limit=50');if(epoch!==contextEpoch)return;const entries=result.events||result.audit||result.entries||[];$('#admin-panel').innerHTML=`<h2>最近的管理操作</h2><p class="muted-note">记录账号与权限变更，不展示儿童观察笔记或验证码。</p><ul class="audit-list">${entries.length?entries.map(e=>`<li><strong>${escapeHTML(e.action||e.type)}</strong><br>${escapeHTML(e.createdAt||e.at||'')} · ${escapeHTML(e.actorEmail||e.actorId||'系统')}<br>对象：${escapeHTML(e.targetId||e.target||'—')}</li>`).join(''):'<li>暂时没有管理操作记录。</li>'}</ul>`}}catch(error){if(epoch!==contextEpoch||session?.user.role!=='admin'||!$('#admin-panel'))return;setMessage('admin-message',error.message,true);$('#admin-panel').innerHTML='<button id="retry-admin" class="button outline">重试</button>';$('#retry-admin').addEventListener('click',renderAdmin)}
}
async function renderAdminUsers(query=''){
 const epoch=contextEpoch,result=await api('/api/admin/users?limit=50&offset=0&query='+encodeURIComponent(query));if(epoch!==contextEpoch||session?.user.role!=='admin')return;const users=result.users||[];
 $('#admin-heading')?.scrollIntoView({block:'start',behavior:'instant'});
 $('#admin-panel').innerHTML=`<form id="admin-search" class="admin-tools"><input id="admin-query" type="search" maxlength="254" placeholder="搜索邮箱" aria-label="搜索用户邮箱" value="${escapeHTML(query)}"><button class="button outline" type="submit">搜索</button><button id="admin-add-user" class="button primary" type="button">邀请用户</button></form><p class="muted-note">共 ${Number(result.total)||users.length} 个账号；每次显示前50条，可按邮箱搜索。停用／归档会撤销登录会话，保留可恢复记录。</p><div class="admin-table-wrap"><table class="admin-table"><thead><tr><th>家长账号</th><th>状态／角色</th><th>关卡权限</th><th>操作</th></tr></thead><tbody>${users.map(u=>`<tr><td>${escapeHTML(u.email)}${u.id===session.user.id?'<br><small>当前管理员</small>':''}</td><td><span class="status-badge ${u.status==='active'?'':'inactive'}">${escapeHTML(({active:'有效',disabled:'已停用',archived:'已归档',invited:'待验证'})[u.status]||u.status)}</span><br>${u.role==='admin'?'管理员':'家长'}</td><td>${u.unlockAll?'全部关卡':Number(u.unlockThrough)>0?'开放至第 '+Number(u.unlockThrough)+' 关':'全部锁定'}</td><td><button class="button outline" data-manage-user="${escapeHTML(u.id)}">管理</button></td></tr>`).join('')||'<tr><td colspan="4" class="admin-empty">没有匹配的账号。</td></tr>'}</tbody></table></div><div id="admin-user-detail"></div>`;
 $('#admin-search').addEventListener('submit',event=>{event.preventDefault();action($('#admin-search button'),()=>renderAdminUsers($('#admin-query').value.trim()),'admin-message')});$('#admin-add-user').addEventListener('click',()=>renderInviteUser());$$('[data-manage-user]').forEach(b=>b.addEventListener('click',()=>renderUserDetail(users.find(u=>u.id===b.dataset.manageUser))));
}
function renderInviteUser(){const root=$('#admin-user-detail');root.innerHTML='<section class="admin-detail"><h2>创建待验证的家长账号</h2><p class="muted-note">只创建待验证账号，不自动登录、不代替邮箱验证。新账号默认没有活动权限。请让家长在首页输入邮箱，获取验证码并完成验证。</p><form id="invite-form" class="account-form"><label>家长邮箱<input id="invite-email" type="email" required maxlength="254" autocomplete="off"></label><button id="invite-user" class="button primary" type="submit">创建待验证账号</button><p id="user-detail-message" class="form-message" role="status"></p></form></section>';$('#invite-form').addEventListener('submit',event=>{event.preventDefault();action($('#invite-user'),async()=>{await api('/api/admin/users',{method:'POST',body:{email:$('#invite-email').value.trim().toLowerCase()}});await renderAdminUsers();setMessage('admin-message','待验证账号已创建。请让家长在首页输入邮箱，获取验证码并完成验证。')},'user-detail-message')});scrollTo('#admin-user-detail')}
function renderUserDetail(user){
 if(!user)return;const self=user.id===session.user.id||user.status==='invited';$('#admin-user-detail').innerHTML=`<section class="admin-detail"><h2>${escapeHTML(user.email)}</h2><p class="muted-note">管理账号和活动权限；此页面不展示儿童笔记。</p><form id="user-role-form" class="account-form"><label>角色<select id="user-role" ${self?'disabled':''}><option value="parent" ${user.role==='parent'?'selected':''}>家长</option><option value="admin" ${user.role==='admin'?'selected':''}>管理员</option></select></label><label>状态<select id="user-status" ${self?'disabled':''}><option value="active" ${user.status==='active'?'selected':''}>有效</option><option value="disabled" ${user.status==='disabled'?'selected':''}>停用（可恢复）</option><option value="archived" ${user.status==='archived'?'selected':''}>归档（可恢复）</option></select></label><button id="save-user-role" class="button outline" type="submit" ${self?'disabled':''}>保存账号设置</button></form><div class="account-section"><h3>关卡权限</h3>${user.role==='admin'?'<p class="muted-note">管理员拥有全部关卡权限，不可通过此表锁定管理员。</p>':''}<form id="user-access-form" class="account-form"><label>开放范围<select id="user-access-mode"><option value="through" ${!user.unlockAll&&user.unlockThrough>0?'selected':''}>开放至指定关卡</option><option value="all" ${user.unlockAll?'selected':''}>一次解锁全部365关</option><option value="locked" ${!user.unlockAll&&!user.unlockThrough?'selected':''}>锁定全部关卡</option></select></label><label id="through-label">开放至第几关<input id="user-access-through" type="number" min="1" max="365" value="${Math.max(1,Number(user.unlockThrough)||1)}"></label><p class="muted-note">这些设置适用于该账号下的所有孩子。锁定活动不会删除已有记录。</p><button id="save-user-access" class="button primary" type="submit" ${user.role==='admin'?'disabled':''}>应用关卡权限</button></form></div><p id="user-detail-message" class="form-message" role="status"></p></section>`;
 const modeChange=()=>$('#through-label').hidden=$('#user-access-mode').value!=='through';$('#user-access-mode').addEventListener('change',modeChange);modeChange();
 $('#user-role-form').addEventListener('submit',event=>{event.preventDefault();action($('#save-user-role'),async()=>{const role=$('#user-role').value,status=$('#user-status').value;if(!confirm(`确认将 ${user.email} 设置为“${role==='admin'?'管理员':'家长'} / ${status==='active'?'有效':status==='disabled'?'停用':'归档'}”？这次调整会保留操作记录。`))return;await api('/api/admin/users/'+encodeURIComponent(user.id),{method:'PATCH',body:{role,status}});await renderAdminUsers();setMessage('admin-message','账号设置已更新。')},'user-detail-message')});
 $('#user-access-form').addEventListener('submit',event=>{event.preventDefault();action($('#save-user-access'),async()=>{const mode=$('#user-access-mode').value,through=Number($('#user-access-through').value);if(mode==='through'&&(!Number.isInteger(through)||through<1||through>365))throw new Error('请输入1至365之间的整数。');const label=mode==='all'?'解锁全部365关':mode==='locked'?'锁定全部关卡':'开放至第 '+through+' 关';if(!confirm(`确认对 ${user.email} ${label}？该操作影响此账号的儿童档案。`))return;await api('/api/admin/users/'+encodeURIComponent(user.id)+'/access',{method:'POST',body:{mode,...(mode==='through'?{through}:{})}});if(user.id===session.user.id){await refreshCurriculum();}await renderAdminUsers();setMessage('admin-message','关卡权限已更新。')},'user-detail-message')});scrollTo('#admin-user-detail');
}
function renderAdminSettings(settings){
 $('#admin-panel').innerHTML=`<div class="account-card wide"><h2>注册与关卡规则</h2><form id="admin-settings-form" class="account-form"><label>允许新注册的邮箱域名<textarea id="allowed-domains" rows="4" maxlength="2000" placeholder="每行一个，例如 example.com">${escapeHTML((settings.allowedDomains||[]).join('\n'))}</textarea></label><p class="muted-note">只接受精确域名，不接受通配符；留空将关闭普通账号的新注册。调整不取消已有账号的登录资格；不会把验证过的邮箱替换为其他地址。</p><label class="check-label"><input id="registration-enabled" type="checkbox" ${settings.registrationEnabled?'checked':''}><span>开放新账号注册（仍需邮箱验证）</span></label><label>逐关开放方式<select id="progression-mode"><option value="manual" ${settings.progressionMode==='manual'?'selected':''}>管理员手动开放</option><option value="sequential" ${settings.progressionMode==='sequential'?'selected':''}>完成前关后自动解锁</option></select></label><p class="muted-note">新账号默认开放第一关。自动模式下，完成前一关后开放下一关；管理员也可手动调整或一次开放全部关卡。</p><button id="save-settings" type="submit" class="button primary">保存注册设置</button><p id="settings-message" class="form-message" role="status"></p></form></div>`;
 $('#admin-settings-form').addEventListener('submit',event=>{event.preventDefault();action($('#save-settings'),async()=>{const allowedDomains=[...new Set($('#allowed-domains').value.split(/[\s,，;；]+/).map(x=>x.trim().toLowerCase()).filter(Boolean))];if(allowedDomains.some(d=>d.includes('@')||d.includes('*')||d.includes('/')))throw new Error('只填写完整邮箱域名，不带@、通配符或网址。');const registrationEnabled=$('#registration-enabled').checked,progressionMode=$('#progression-mode').value;if(!confirm('确认更新注册域名与关卡规则？已有账号记录不会删除。'))return;const result=await api('/api/admin/settings',{method:'PUT',body:{allowedDomains,registrationEnabled,progressionMode}});authConfig={...authConfig,...result};setMessage('settings-message','设置已保存。新注册将按这些规则校验。')},'settings-message')});
}
function bindInterface(){
 $('#close-safety').addEventListener('click',()=>closeDialog('safety-dialog'));$('#close-diagram').addEventListener('click',()=>closeDialog('diagram-dialog'));
 $$('dialog').forEach(d=>{d.addEventListener('cancel',event=>{event.preventDefault();closeDialog(d.id)});d.addEventListener('keydown',trapDialogFocus)});
 $('#map-current-month').addEventListener('click',()=>setMapMonth(String(monthForDay(state.day))));$('#map-all-year').addEventListener('click',()=>setMapMonth('all'));
 $('#day-prev').addEventListener('click',()=>chooseDay(state.day-1));$('#day-next').addEventListener('click',()=>chooseDay(state.day+1));$('#today-btn').addEventListener('click',()=>{if(chooseDay(recommendation()))toast('每天一个主活动即可，按已开放的关卡慢慢探索。')});
 $$('.map-trigger').forEach(btn=>btn.addEventListener('click',()=>{if(!session||!activeChild||!experiments.length)return;$('#map-feedback').hidden=true;renderMap();openDialog('day-map')}));$('#close-map').addEventListener('click',()=>closeDialog('day-map'));$('#day-map').addEventListener('click',event=>{if(event.target===$('#day-map')){const r=$('#day-map').getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog('day-map')}});
 $$('[data-filter]').forEach(btn=>btn.addEventListener('click',()=>{filter=btn.dataset.filter;$$('[data-filter]').forEach(b=>b.setAttribute('aria-pressed',String(b===btn)));renderMap()}));$('#map-month').value=mapMonth;$('#map-month').addEventListener('change',event=>{setMapMonth(event.target.value)});$('#map-search').addEventListener('input',event=>{mapQuery=event.target.value;renderMap()});
 $('#child-switch').addEventListener('change',event=>selectChild(event.target.value));$('#retry-save').addEventListener('click',()=>{if(saveConflict){location.hash='#account';renderFamily()}else if(curriculumError&&!dirty)reloadDots();else flushSave()});
}
async function init(){
 bindInterface();clearStaleDialogState();syncView();try{authConfig=await api('/api/auth/config');let result;try{result=await api('/api/session')}catch(error){if(error.status!==401)throw error}if(result)await acceptSession(result,{resume:true});else{clearPreparation();renderAuth();syncView()}}catch(error){$('#account-content').innerHTML='<div class="service-error"><h1 id="account-heading">家庭空间暂时没有连接</h1><p>'+escapeHTML(error.message)+'</p><p class="muted-note">为保护账号和儿童资料，连接失败时不会开放实验内容，也不会自动上传旧记录。</p><button id="retry-connection" class="button primary">重新连接</button></div>';$('#retry-connection').addEventListener('click',()=>location.reload());syncView()}
}
init();
function archivedChildrenHTML(){const list=children.filter(c=>c.archivedAt);return list.length?`<section class="account-section"><details><summary>已归档的儿童档案（${list.length}）</summary><p class="muted-note">归档保留记录。恢复后可继续探索，每个账号最多8个有效档案。</p>${list.map(c=>`<div class="form-actions"><span>${escapeHTML(c.nickname)} · ${escapeHTML(c.ageBand)}岁</span><button type="button" class="text-button" data-restore-child="${escapeHTML(c.id)}">恢复档案</button></div>`).join('')}<p id="restore-message" class="form-message" role="status"></p></details></section>`:''}
function bindRestoreChildren(){$$('[data-restore-child]').forEach(b=>b.addEventListener('click',()=>action(b,async()=>{const owner=session,epoch=contextEpoch,id=b.dataset.restoreChild;if(!await ensureSaved()||session!==owner||contextEpoch!==epoch)return;const result=await api('/api/children/'+encodeURIComponent(id)+'/restore',{method:'POST',body:{}});if(session!==owner||contextEpoch!==epoch)return;children=children.map(c=>c.id===result.child.id?result.child:c);await selectChild(result.child.id,{skipSave:true});location.hash='#lab';syncView()},'restore-message')))}
function setAuthBusy(busy){authBusy=busy;$$('#change-email,#resend-code,#auth-consent,#switch-password-login').forEach(b=>{b.disabled=busy||(b.id==='resend-code'&&Date.now()<resendAt)});if($('#auth-email'))$('#auth-email').readOnly=busy;if($('#auth-code'))$('#auth-code').readOnly=busy}

async function exclusiveFamilyMutation(work){
 if(familyMutationBusy)throw new Error('上一项家庭资料操作尚未完成，请稍候。');familyMutationBusy=true;
 const nodes=[...document.body.children].filter(n=>!['SCRIPT','STYLE'].includes(n.tagName)),prior=nodes.map(n=>n.inert);nodes.forEach(n=>n.inert=true);
 const notice=document.createElement('div');notice.className='family-operation-notice';notice.setAttribute('role','status');notice.textContent='正在保存家庭资料，请稍候。为避免记录冲突，暂时暂停编辑。';document.body.append(notice);
 try{return await work()}finally{familyMutationBusy=false;notice.remove();nodes.forEach((n,i)=>n.inert=prior[i])}
}
